recipes.each do |attrs|
  Recipe.find_or_create_by!(name: attrs[:name]) do |r|
    r.summary = attrs[:summary]
    r.ingredients = attrs[:ingredients]
    r.instructions = attrs[:instructions]
  end
end

puts "Seeded #{Recipe.count} recipes."
